const l="/dashboard/atividades-recentes-csv";async function p(){const n=document.getElementById("atividades-recentes-container");if(n)try{const e=await fetch(l,{headers:{Accept:"text/csv"}});if(!e.ok)throw new Error("Falha ao carregar atividades");const c=await e.text(),r=h(c);m(n,r)}catch{n.innerHTML='<div class="card-body"><p style="color:var(--text-3)">Nao foi possivel carregar Atividades Recentes</p></div>'}}function h(n){const e=n.split(/\r?\n/).filter(t=>t.trim()!=="");if(e.length===0)return[];const c=e[0].split(",").map(t=>t.trim().replace(/^"|"$/g,"")),r=[];for(let t=1;t<e.length;t++){const o=e[t].split(",").map(a=>a.trim().replace(/^"|"$/g,"")),d={};c.forEach((a,s)=>{d[a]=o[s]||""}),r.push(d)}return r}function m(n,e){if(!e.length){n.innerHTML='<div class="card-body"><p style="color:var(--text-3)">Nenhuma atividade registrada</p></div>';return}const c=document.createElement("table");c.className="table";const r=document.createElement("thead"),t=document.createElement("tr");Object.keys(e[0]).forEach(d=>{const a=document.createElement("th");a.textContent=d,t.appendChild(a)}),r.appendChild(t),c.appendChild(r);const o=document.createElement("tbody");e.forEach(d=>{const a=document.createElement("tr");Object.values(d).forEach(s=>{const i=document.createElement("td");i.textContent=s,a.appendChild(i)}),o.appendChild(a)}),c.appendChild(o),n.innerHTML="",n.appendChild(c)}function u(){p()}export{u as initAtividadesRecentes};
